"""Eleventh batch (dragons plan E5): Voidmarch (backdrop, boss, enemy sheet and their attack poses) and the Wyrm breed
(four life stages on one sheet, then the attack sheet). Run from the gen folder: `python3 v2/jobs11.py idle`, generate,
then `python3 v2/jobs11.py attack`. The Wyrm sheet uses refs/dragon-colors.png (the original adult dragon) for colors."""
import os, shutil, sys
STYLE = open('v2/style.txt').read().strip()
HEAD = "Use your built-in image generation tool to create one image and save it as ./v2/out/{name}.png (landscape, about 1536x1024). Do not write code to draw it; generate it with the image tool. The FIRST attached image is the STYLE reference only: match its line weight, flat two-tone cel shading, shape language and level of simplicity exactly, so this looks like art from the same game. Do not copy its subject or its colors unless told to."
TAIL = "Perfectly flat solid #00ff00 background everywhere outside the artwork. Do not use bright green anywhere in the artwork itself (use dark, olive or teal greens if something must be green). No ground, no cast shadows, no text, no labels, no numbers, no borders, no frames."
KEYS = "Colors are fixed for every one of them: body pure red-orange with a darker red shadow tone; belly plates, wing membranes and back spines golden yellow with an orange-gold shadow tone; horns and claws cream; eye white with a dark brown iris. Use no other reds, oranges or yellows anywhere. Every tail ends in a plain tapered point (no flame, no ornament)."
os.makedirs('v2/prompts', exist_ok=True); os.makedirs('v2/out', exist_ok=True); os.makedirs('v2/refs', exist_ok=True)

def job(name, body, ref=None):
    open(f'v2/prompts/{name}.txt', 'w').write(HEAD.format(name=name) + "\n\n" + body + "\n\n" + STYLE + "\n")
    if ref: shutil.copy(ref, f'v2/refs/{name}.png')

BOSS = "Strict side profile facing RIGHT, full body, standing on the ground, whole creature inside the frame with a clear margin, nothing cropped. A big imposing boss enemy for a side-view battle: menacing and grumpy but still funny and all-ages. " + TAIL
NULLMAW = "the Nullmaw, a huge squat stone toad that lives at the bottom of a chasm: a wide heavy body of dark slate-gray stone plates with lighter gray shadow tones, a huge wide mouth with a long purple tongue curled at the tip, small glowing pale-violet eyes on top of its head, stubby strong legs, and in the middle of its round belly a big swirling hole of dark indigo nothingness with a thin pale violet rim, a few small rock chunks floating around it, a hungry greedy expression"
SHEET = ["Rift Mite: a tiny round dark-indigo bug with six stubby legs and a hollow black hole with a violet rim on its back, a little pebble floating above the hole, beady curious eyes",
         "Shardhorn Goat: a stocky mountain goat in slate gray and tan with big curled horns and three sharp floating rock shards orbiting its horns, a stubborn scowl",
         "Gloom Gulper: a round floating dark-violet blob that is mostly a huge open mouth with a black inside, two tiny eyes on top, small fin-like flaps, very hungry looking",
         "Rubble Crab: a chunky crab in brown and gray stone with big pincers, carrying a large floating boulder above its back instead of a shell, very proud expression",
         "Echo Bat: a small dark-indigo bat with gigantic dish-shaped ears much bigger than its body and hollow glowing pale-violet eyes, hanging in a hover with wings spread",
         "Voidstrider: a tall lanky stone heron in dark gray with long thin legs, a long sharp beak, a stern bored face, and a round window of swirling indigo nothingness in the middle of its chest, much tougher looking than the others"]
SHEET_BODY = "SUBJECT: a sheet of six separate enemy creatures for a side-view battle game, arranged in a grid of 3 columns by 2 rows, evenly spaced. Each creature is fully separate with wide green space around it; none touch or overlap. Every one is in strict side profile facing RIGHT, full body, nothing cropped, drawn at a similar size (the sixth is the mini-boss: make it look tougher, not larger than its cell). They are grumpy, funny, all-ages creatures from a broken rocky land at the edge of a void. Reading order, left to right, top row then bottom row:\n" + "\n".join(f"{i+1}) {t}." for i, t in enumerate(SHEET)) + "\n" + TAIL
BD = " COMPOSITION RULES: full-bleed scene to every edge, NO characters or creatures. The bottom quarter of the image is wide, flat, fairly empty ground where fighters will stand: calm and low in detail, with a soft pool of lighter color in the middle; props sit only near the far left and right edges. The middle band of the picture is calmer and lower in contrast than the top, so characters placed on it stand out. One clear light source (sun, moon or glow) sits in the upper middle of the sky. For this background, adapt the style: scenery is flat color shapes with two or three value steps and NO dark ink outlines (outlines are reserved for characters), distant layers lighter and hazier, colors a little softer and less saturated than the reference character. No text, no border."
MARCH = "the Voidmarch, a broken rocky plateau at twilight on the edge of a great void: flat slate-gray stone ground with a lighter pool in the middle, a jagged broken rock pillar with a small floating boulder above it at the far left edge, a cracked ledge with a few floating rock shards at the far right edge, behind them a huge dark round chasm of indigo nothingness with a soft violet rim fading into haze, floating rock islands in the distance, a pale violet sky with a big soft pale moon in the upper middle."
WYRM = ("a WYRM, a different kind of dragon from the reference: a long serpent-like body that curves in a gentle S along the ground, four short stubby legs, small wings near the shoulders, a long neck, a wise head with two short horns and long whisker-like barbels, and a long tail. Graceful, calm and wise looking.")
STAGES = ("Reading order, left to right, top row then bottom row: 1) HATCHLING: a tiny baby wyrm, big head and big eyes, tiny wing nubs, about half the length of the elder; "
          "2) JUVENILE: a young wyrm, longer body, small horns; 3) ADULT: a full grown wyrm; "
          "4) ELDER: the largest, an old wise wyrm with long curved horns, long flowing barbels and a few extra spines. Each stage is clearly bigger than the one before.")
GRID = "Arrange them in a grid of 2 columns by 2 rows, evenly spaced. Each one is fully separate with wide green space around it; none touch or overlap. Every one is in strict side profile facing RIGHT, full body, nothing cropped."
SAME = " This is the SAME creature as the SECOND attached image: keep its exact design, colors, markings and proportions, drawn at the same size in the frame. Strict side profile facing RIGHT, full body, feet on the same ground line, whole creature inside the frame with a clear margin, nothing cropped. Do NOT draw any impact effects, speed lines, breath or projectiles. " + TAIL

step = sys.argv[1] if len(sys.argv) > 1 else 'idle'
if step == 'idle':
    job('bg-voidmarch', "SUBJECT: a battle backdrop. " + MARCH + BD)
    job('boss-nullmaw', "SUBJECT: " + NULLMAW + ". " + BOSS)
    job('sheet-voidmarch', SHEET_BODY)
    job('wyrm-stages', "SUBJECT: a sheet of the SAME " + WYRM + " at four life stages. " + GRID + " " + STAGES + " " + KEYS +
        " The SECOND attached image is the existing dragon from the same game: copy its colors, outline and finish exactly, but NOT its body shape (this one is a long serpent-like wyrm). " + TAIL, ref='v2/refs/dragon-colors.png')
else:
    job('boss-nullmaw-attack', "SUBJECT: the boss in its ATTACK pose: lunging forward to the right, huge mouth wide open with the tongue lashing out, eyes blazing, front legs pushing forward." + SAME, ref='v2/out/boss-nullmaw.png')
    job('sheet-voidmarch-attack', "SUBJECT: the SAME six creatures as the SECOND attached image, in the same grid of 3 columns by 2 rows, in the same order and at the same size, each one now in an ATTACK pose: lunging or leaning forward to the right, mouth open, horns, pincers, ears or beak thrust forward, fierce expression. Keep every creature's exact design, colors and proportions; only the pose changes. Each creature is fully separate with wide green space around it; none touch or overlap. All in strict side profile facing RIGHT, full body, nothing cropped. Do NOT draw any impact effects, speed lines or projectiles, and keep any floating rocks close to their creature. " + TAIL, ref='v2/out/sheet-voidmarch.png')
    job('wyrm-stages-attack', "SUBJECT: the SAME four wyrms as the SECOND attached image, in the same grid of 2 columns by 2 rows, in the same order and at the same sizes, each now in an ATTACK pose: rearing the front of its body up and lunging its head forward to the right, mouth wide open roaring, small wings flared. Keep each one's exact design, colors and proportions; only the pose changes. " + KEYS + " Inside of the mouth dark maroon with a pink tongue and cream teeth. Do NOT draw any fire, breath, smoke or effects. Each one fully separate with wide green space; none touch. Strict side profile facing RIGHT, full body, nothing cropped. " + TAIL, ref='v2/out/wyrm-stages.png')
print(sorted(f for f in os.listdir('v2/prompts') if 'void' in f or 'wyrm' in f or 'nullmaw' in f))
